package com.lamggm.rospocket;
import android.graphics.*;import android.view.*;import org.json.*;import java.lang.reflect.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=31) @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class GaugeCanvasTest {
 static final int DATA=0xff4688d4;
 Method sample(){Method found=null;for(Method m:MetricCard.class.getDeclaredMethods())if(m.getName().equals("sample"))found=m;assertNotNull("Cards need a typed numeric sample input; display text is not a source",found);found.setAccessible(true);return found;}
 MetricCard card(String mode)throws Exception{MetricCard c=new MetricCard(RuntimeEnvironment.getApplication());DashboardBoard b=new DashboardBoard(c.getContext());b.bind(DashboardLayout.defaults().display("watch0",new DashboardLayout.Display(mode,"linear.x",-2,8,"m/s")),null);b.addCard("watch0","Watch1",c,null);c.bind(0,1,"rt/speed","geometry_msgs::msg::dds_::Twist_","Recebendo","not the numeric source",true);c.measure(View.MeasureSpec.makeMeasureSpec(400,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(260,View.MeasureSpec.EXACTLY));c.layout(0,0,400,260);return c;}
 JSONArray fields(Object value)throws Exception{return new JSONArray().put(new JSONObject().put("path","linear.x").put("value",value).put("state","finite"));}
 int pixels(MetricCard c){Bitmap b=Bitmap.createBitmap(400,260,Bitmap.Config.ARGB_8888);c.draw(new Canvas(b));int count=0;for(int y=65;y<245;y++)for(int x=12;x<388;x++)if(b.getPixel(x,y)==DATA)count++;return count;}
 @Test public void oneCellGaugeRetainsPortableSpanWithCompactRenderedHeight(){android.content.Context ctx=RuntimeEnvironment.getApplication();DashboardBoard b=new DashboardBoard(ctx);b.bind(DashboardLayout.defaults().display("watch0",new DashboardLayout.Display("gauge","data",0,100,"%")),null);MetricCard c=new MetricCard(ctx);b.addCard("watch0","Watch1",c,null);b.measure(View.MeasureSpec.makeMeasureSpec(1200,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(0,View.MeasureSpec.UNSPECIFIED));b.layout(0,0,1200,b.getMeasuredHeight());assertEquals(1,b.layout().get("watch0").height);assertEquals("User requested compact 1x1, without rewriting portable layout",Math.round(120*ctx.getResources().getDisplayMetrics().density),c.getHeight());}
 @Test public void layoutOnlyRefreshDoesNotEraseTheCurrentTypedSample()throws Exception{MetricCard c=card("gauge");sample().invoke(c,fields(3),true);int before=pixels(c);assertTrue(before>40);DashboardBoard board=(DashboardBoard)c.getParent().getParent();board.edit();assertEquals(before,pixels(c));}
 @Test public void barClampsOnlyItsDrawingAndRejectsStringsNullNonfiniteAndWrongPath()throws Exception{MetricCard c=card("bar");Method m=sample();m.invoke(c,fields(20),true);assertTrue(pixels(c)>100);assertTrue(c.getContentDescription().toString().contains("20.000"));assertTrue(c.getContentDescription().toString().contains("Fora da escala"));for(Object v:new Object[]{"3",JSONObject.NULL}){m.invoke(c,fields(v),true);assertEquals(0,pixels(c));}m.invoke(c,new JSONArray().put(new JSONObject().put("path","angular.x").put("value",3).put("state","finite")),true);assertEquals(0,pixels(c));m.invoke(c,new JSONArray().put(new JSONObject().put("path","linear.x").put("value",3).put("state","nan")),true);assertEquals(0,pixels(c));}
 @Test public void nativePreviewsAreSyntheticTestOnly()throws Exception{String folder=System.getenv("POCKET_GAUGE_PREVIEW_DIR");if(folder==null)return;java.nio.file.Path out=java.nio.file.Paths.get(folder);java.nio.file.Files.createDirectories(out);for(String theme:new String[]{"light","dark"})for(int width:new int[]{400,1200}){android.content.Context ctx=RuntimeEnvironment.getApplication();UiTheme.save(ctx,theme);DashboardBoard board=new DashboardBoard(ctx);DashboardLayout layout=DashboardLayout.defaults();String[] modes={"number","gauge","bar","gauge"};for(int i=0;i<4;i++)layout=layout.display("watch"+i,new DashboardLayout.Display(modes[i],"linear.x",-2,8,"m/s")).resize("watch"+i,2,1);board.bind(layout,null);for(int i=0;i<4;i++){MetricCard c=new MetricCard(ctx);board.addCard("watch"+i,"Watch"+(i+1),c,null);c.bind(i,4,"rt/fixture/speed_"+i,"geometry_msgs::msg::dds_::Twist_","SYNTHETIC HOST", "3.0",i!=3);c.sample(fields(i==2?12:3),i!=3);}board.measure(View.MeasureSpec.makeMeasureSpec(width,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(0,View.MeasureSpec.UNSPECIFIED));board.layout(0,0,width,board.getMeasuredHeight());Bitmap image=Bitmap.createBitmap(width,board.getHeight(),Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(image);canvas.drawColor(VisualButton.bg(ctx));board.draw(canvas);try(java.io.OutputStream stream=java.nio.file.Files.newOutputStream(out.resolve("gauges-"+width+"-"+theme+"-HOST-SYNTHETIC.png"))){image.compress(Bitmap.CompressFormat.PNG,100,stream);}}}
 @Test public void gaugeUsesTypedSelectedFieldAndSuppressesStaleAndMissingValues()throws Exception{MetricCard c=card("gauge");Method m=sample();m.invoke(c,fields(3),true);assertTrue("Gauge data ink must be drawn",pixels(c)>40);assertTrue(c.getContentDescription().toString().contains("3"));m.invoke(c,fields(3),false);assertEquals(0,pixels(c));assertTrue(c.getContentDescription().toString().contains("Sem dados atuais"));m.invoke(c,new JSONArray(),true);assertEquals(0,pixels(c));}
}
